      "detail": "相传尧舜之时，天下洪水滔天，百姓苦不堪言。舜帝继位后，任命大禹治水。禹吸取父亲鲧堵水失败的教训，改用疏导之法，带领百姓开山凿渠、引水入海。他历时十三年，三过家门而不入，终于平定水患，百姓得以安居乐业。舜帝感念禹的功德与贤能，依照部落联盟推举首领的传统，将帝位禅让给禹。禹登基后，定都阳城（今河南登封），建立夏朝——这是中国历史上第一个王朝",
