      "detail": "春秋末期，晋国公室衰微，实权落入赵、韩、魏、智四卿之手。前453年，赵、韩、魏三家联合灭掉最强的智氏并瓜分其地，晋国名存实亡。至前403年，周威烈王正式册封三家为诸侯，晋国被彻底肢解为赵、韩、魏三国。司马光《资治通鉴》即以此为开端，视作“礼崩乐坏”的标志性事件，战国七雄格局由此奠定。                                                                                                                                                  前453 晋阳之战，智氏灭，三家实分晋 → 前445 魏文侯即位，用李悝变法 → 前438 晋幽公立，公室名存实亡 → 前403 周威烈王册命三晋为诸侯（战国开端） → 前386 田和列为齐侯 → 前376 废晋静公，晋绝祀 → 前354 桂陵之战 → 前341 马陵之战 → 前260 长平之战 → 前221 秦统一",
