      "blurb": "孙膑在马陵之战中设伏歼灭魏军主力，庞涓自杀，魏国霸业终结",
      "detail": "魏国攻韩，韩国求救于齐，齐再度以田忌、孙膑率军救韩，直趋大梁。孙膑用“减灶诱敌”之计，逐日减灶制造齐军溃逃假象，庞涓轻敌弃步兵、率精锐昼夜追击。齐军在马陵（今山东郯城一带）险道设伏，万弩齐发，魏军溃败，庞涓自刎（一说战死），太子申被俘。魏国霸权自此终结，齐国取代魏国称雄东方",
