      "blurb": "秦始皇连接修筑万里长城，防御北方游牧民族，成为中华民族的象征之一",
      "detail": "为长久防御匈奴，秦将战国时秦、赵、燕三国北边的旧长城连接增筑，西起临洮（今甘肃岷县），东至辽东，蜿蜒万里，史称“万里长城”。工程动用军民数十万，监筑严酷，民夫不堪劳苦，民间遂有孟姜女哭长城的传说流传。长城此后历代增修，成为农耕文明抵御游牧势力的标志性防线",
