    "ev:废分立郡、书同文车同轨、统一货币度量衡": {
      "__new": true,
      "name": "废分立郡、书同文车同轨、统一货币度量衡",
      "year": -221,
      "region": "china",
      "era": "qin",
      "place": "陕西西安（咸阳）",
      "lng": 108.9,
      "lat": 34.3,
      "importance": 5,
      "blurb": "秦始皇统一后推行废分封行郡县、书同文、车同轨、统一货币度量衡等一系列巩固统一的重大举措",
      "detail": "丞相王绾等建议分封诸子为王以镇远方，廷尉李斯力主郡县，认为分封是春秋战国战乱之源。秦始皇采纳李斯之议，废分封制，分天下为三十六郡，后增至四十余郡；郡设守、尉、监，县设令、长，皆由中央任免、不得世袭。中央集权的官僚体制取代封建血缘政治，成为此后历代王朝的基本政制框架。【补充】战国时各国文字形体异形，“言语异声，文字异形”。秦统一后，始皇命丞相李斯等整理文字，以秦系文字为基础定小篆为标准字体，颁行全国；又命李斯作《仓颉篇》、赵高作《爰历篇》、胡毋敬作《博学篇》作为规范字书。民间及官府文书书写渐用简便的隶书。文字统一消除了各地交流障碍，对维护国家统一和文化传承意义重大。【补充】战国时各国车轨宽窄不一，道路关卡林立。秦统一后下令“舆六尺”、车同轨，规定车辆轨距全国一律，便利车行；又以咸阳为中心修筑驰道、直道，形成通达全国的道路网络，并拆除原六国的关塞堡垒。交通标准化加强了中央对各地的控制，也促进了经济往来与人员流通。【补充】战国货币形制混乱：布币、刀币、蚁鼻钱、圜钱并行。秦统一后废止各国旧币，规定黄金为上币、以镒为单位，铜钱为下币，统一为圆形方孔的“半两钱”，禁止民间私铸。方孔圆钱形制便于穿绳携带、铸造规范，此后沿用两千余年，成为中国传统铸币的标准形态。【补充】战国时各国度、量、衡制度各异，换算繁难。秦以商鞅变法时确立的制度为基准推行全国，颁发了大量刻有诏书的度量衡标准器，规定六尺为步、二百四十步为亩等；又推行“行同伦”，规范各地行为伦理。度量衡统一便利了赋税征收、商品交易与工程营造，是巩固统一的重要经济举措",
      "figures": [
        "秦始皇",
        "李斯"
      ],
      "video": {
        "bili": "秦始皇统一措施 郡县制"
      },
      "tier": 2
    },
