      "detail": "统一后匈奴仍盘踞河南地（河套），时常南下侵扰。前215年，始皇派大将蒙恬率三十万大军北击匈奴，收复河南地；次年渡河攻取高阙、阳山、北假，控制阴山一线。秦在当地设四十四县，移民垦戍，筑亭障以御胡。匈奴被逐出七百里外，“胡人不敢南下而牧马”，北方边患一时缓解",
