      "detail": "景帝采御史大夫晁错《削藩策》，先后削楚、赵及吴之郡地。吴王刘濞蓄谋已久，联合胶西、楚、赵等七国，以“清君侧、诛晁错”为名起兵，发兵二十余万西进，赵亦发兵，胶西诸国围齐。景帝误信袁盎之言腰斩晁错以谢诸侯，叛军不退。周亚夫以太尉率军，行昌邑坚壁不出，遣轻骑断吴楚粮道，叛军饥疲，决战大败，刘濞逃至东越被杀。三月而乱平，诸侯王势力遭重创，中央集权大为加强",
