      "detail": "东汉初年，刘秀在统一中原后，将战略重心转向西北与西南的割据势力。建武六年（30年）起，汉军先后对割据陇右的隗嚣和割据巴蜀的公孙述发动进攻。经过数年苦战，汉军于建武八年攻破隗嚣残部，随后大军入蜀，于建武十二年（36年）攻克成都，公孙述战死。至此，刘秀彻底扫平了陇蜀地区的割据势力，完成了全国的统一大业。这场战争不仅消除了东汉政权最后的内部威胁，也结束了自新莽末年以来长达十余年的分裂割据局面，使黄河流域与长江流域重新归于一个中央政权的管辖之下",
