      "detail": "公元220年，曹操病逝于洛阳，其子曹丕继位为魏王。同年十月，曹丕在群臣劝进下，于繁阳正式逼迫汉献帝刘协禅让，终结了延续四百余年的汉朝统治，建立魏国，定都洛阳，改元黄初。此举标志着三国时代的正式开启。曹丕代汉并非突发政变，而是曹氏家族长期掌控朝政、积累政治资本的结果。他通过九品中正制拉拢士族，巩固政权合法性。汉献帝被贬为山阳公，得以善终。曹丕称帝后，蜀汉刘备与东吴孙权相继称帝，形成三足鼎立之势，中国历史进入分裂割据的新阶段",
