      "detail": "赤壁一战，孙权与刘备合力击退曹操，自此据有江东六郡。219年，他背盟袭取荆州、擒杀关羽，与蜀汉彻底交恶。曹丕称帝后，孙权暂且向魏称臣，受封吴王；222年夷陵大胜后，他不再奉魏正朔，自建年号“黄武”，形同独立。此后诸葛亮主政蜀汉，重修盟好，默认其帝号以共抗曹魏。229年四月，孙权在武昌南郊设坛告天，即皇帝位，国号吴，改元黄龙，追尊父孙坚为武烈皇帝，立子孙登为太子。同年九月迁都建业。蜀汉遣陈震赴武昌庆贺，两国约定“参分天下”。至此，魏、蜀、吴三方皆已称帝，三国鼎立的法理格局正式确立",
