      "detail": "公元234年春，诸葛亮发动最后一次北伐，率十万大军出斜谷，屯兵五丈原，与魏将司马懿隔渭水对峙。为持久作战，诸葛亮在渭滨分兵屯田，作长期打算。司马懿坚守不出，双方相持百余日。诸葛亮夙夜操劳，事必躬亲，终因积劳成疾，于八月病逝于五丈原军中，享年五十四岁。临终前，他密授退军方略，命杨仪、费祎等有序撤军，并设计吓退追兵。蜀军安全退回汉中，魏军不敢追击。诸葛亮之死标志着蜀汉主动进攻时代的结束，此后姜维虽继续北伐，但国力日衰，再难有大规模攻势，蜀汉转入守势",
