      "blurb": "祖逖率军北伐收复黄河以南地区，\"闻鸡起舞\"成为励志典故",
      "detail": "东晋初年，北方陷入战乱，大量流民南渡。奋威将军祖逖心怀故土，主动请缨北伐。他率领部曲百余家渡江，在淮阴冶铁铸兵，招募流民，组建军队。祖逖治军严明，与将士同甘共苦，成功收复黄河以南大片失地，并迫使后赵石勒不敢轻易南侵。然而，东晋朝廷内部矛盾重重，对北伐缺乏实质支持，甚至派戴渊牵制。祖逖忧愤成疾，于321年病逝，北伐事业随之夭折，收复的领土逐渐得而复失",
