    "ev:朱温代唐建梁": {
      "__new": true,
      "name": "朱温代唐建梁",
      "year": 907,
      "region": "china",
      "era": "五代十国",
      "place": "河南开封（汴州）",
      "lng": 114.3,
      "lat": 34.8,
      "importance": 5,
      "blurb": "朱温逼迫唐哀帝禅让，建立后梁，唐朝正式灭亡，五代十国开始。907年宣武节度使朱温逼唐哀帝禅位、建国号梁并定都开封，享国近三百年的大唐就此灭亡",
      "detail": "天祐四年（907年）四月，原黄巢部将、后降唐封梁王的朱温废黜唐哀帝李柷，自立为帝，国号大梁，改元开平，定都东京开封府，史称后梁。此举正式终结了唐朝。但后梁失去传统正统光环，各地藩镇多持观望或自立态度，河东李克用、西川王建等拒不承认其帝号，为后续数十年的混战埋下了伏笔。中国历史进入五代十国的分裂时期，中原政权更迭频繁。唐末藩镇割据，宦官专权，朝政败坏。黄巢起义被平定后，宣武节度使朱温势力坐大，先后击败秦宗权、朱瑄等对手，逐步占据中原。901年起，朱温挟持唐昭宗迁都洛阳，又于904年弑杀昭宗，另立年幼的李柷为帝，即唐哀帝，朝政尽归其手。907年，朱温逼迫唐哀帝禅位，自立为帝，国号梁，定都开封，改元开平，享国近三百年的大唐就此灭亡。朱温建梁标志着五代十国的开端，此后中原相继出现后梁、后唐、后晋、后汉、后周五个短命王朝，政权更迭频繁、战乱不休，直到北宋才重新走向统一。后梁与河东李克用、李存勖父子长期争战，最终于923年为后唐所灭",
      "figures": [
        "朱温",
        "唐哀帝。朱温",
        "唐哀帝",
        "李克用"
      ],
      "video": {
        "bili": "朱温建梁 唐朝灭亡。朱温 后梁 五代十国"
      },
      "tier": 2
    },
