      "detail": "绍兴三十一年（1161年）十一月，淮西制置使王权畏敌溃退，中书舍人虞允文奉命赴采石矶（今安徽马鞍山西南）犒师。见宋军群龙无首，他临危受命，整顿散兵约一万八千人，激励将士迎战。宋军以海鳅船配合霹雳炮、神臂弓大破金军渡江船只，次日又在杨林河口取胜，金军损失战船三百余艘。完颜亮转攻瓜洲时强令“三日渡江”，引发军变被杀，金军北撤，南宋转危为安",
