      "detail": "1259年蒙哥汗在合州钓鱼城战死，蒙古汗位空悬。次年三月，忽必烈在开平（今内蒙古正蓝旗）自行召集忽里台大会称大汗；同月，幼弟阿里不哥在和林被蒙古本土贵族推举为大汗，兄弟争位爆发。经过四年内战，阿里不哥兵败归降，忽必烈确立统治。此举虽保住汗位，却导致四大汗国逐渐离心，统一的蒙古帝国走向分裂",
