    "ev:建国号元": {
      "__new": true,
      "name": "建国号元",
      "year": 1271,
      "region": "china",
      "era": "yuan",
      "place": "北京（大都）",
      "lng": 116.4,
      "lat": 39.9,
      "importance": 5,
      "blurb": "忽必烈正式建国号大元，定都大都（北京），元朝正式建立。1271年忽必烈取《易经》大哉乾元之义定国号为元，迁都大都，标志蒙古政权向中原王朝转变",
      "detail": "忽必烈是成吉思汗之孙，蒙哥汗之弟。蒙哥汗死后，他于1260年在开平（后称上都）即大汗位，建元中统，采用汉法治理中原。他重用刘秉忠、王文统等汉族谋士，推行劝农、设官、立钞法等一系列措施。至元八年（1271年），忽必烈取《易经》大哉乾元之义，正式定国号为元，标志蒙古政权由草原汗国向中原王朝的转变。次年（1272年），他迁都大都（今北京），营建都城中枢。至元十六年（1279年）灭南宋，完成全国统一，元朝成为中国历史上首个由少数民族建立的大一统王朝，疆域空前辽阔，对后世政治格局影响深远",
      "figures": [
        "忽必烈。忽必烈",
        "刘秉忠",
        "王文统"
      ],
      "video": {
        "bili": "忽必烈 元朝 大哉乾元"
      },
      "tier": 2
    },
