    "ev:永乐迁都": {
      "__new": true,
      "name": "永乐迁都",
      "year": 1421,
      "region": "china",
      "era": "ming",
      "place": "北京（北京/顺天府）",
      "lng": 116.4,
      "lat": 39.9,
      "importance": 5,
      "blurb": "明成祖朱棣迁都北京，\"天子守国门\"，奠定此后五百年中国政治中心格局。1421年明成祖将都城由南京迁往北京，奠定北京近六百年国都的地位",
      "detail": "明成祖以北平为“龙兴之地”且便于控御北方边防，自永乐四年（1406年）起营建北京城，修筑宫殿、城墙与坛庙，并疏浚大运河保障漕运。永乐十八年（1420年）宫殿建成，次年正式迁都，改北京为京师，南京留为陪都。迁都强化了北部防线，但也使政治中心与经济重心分离，漕运负担长期沉重。明成祖朱棣通过靖难之役夺得帝位后，深感南京偏处东南、不便控制广大的北方，加之北平是其经营多年的根据地，遂决意迁都。永乐元年（1403年）他改北平为北京，随后征调百万工匠、民夫，历时十余年营建宫城、皇城与内城，紫禁城规制宏丽，成为当时世界上最大的宫殿群。永乐十八年（1420年）北京宫殿告成，次年（1421年）正式迁都北京，以南京为留都，保留一套中央机构。迁都加强了对北方和蒙古的防御与控制，也有利于经略东北和西北，从此奠定了北京作为明清两代政治中心近六百年的地位，对后世都城格局与政治地理影响深远",
      "figures": [
        "朱棣。朱棣",
        "蒯祥"
      ],
      "video": {
        "bili": "永乐迁都 北京 朱棣"
      },
      "tier": 2
    },
