      "blurb": "张居正推行一条鞭法，将各种赋役合并折银征收，是中国赋税制度的重大变革",
      "detail": "万历九年（1581年），张居正将在部分地区试行的赋役改革推广全国，实行“一条鞭法”：将田赋、徭役及各项杂税合并折银征收，按亩计税、官府雇人应役，并简化征收环节。此举减轻了无地少地农民的负担，提高了征收效率，也反映出白银在经济生活中地位的上升，是中国赋役制度史上的重要转折",
