      "detail": "康熙二十八年（1689年），中俄双方在尼布楚（今俄罗斯涅尔琴斯克）谈判签约，划定两国东段边界：以外兴安岭至海、格尔必齐河与额尔古纳河为界，岭南属中国，岭北属俄国。这是中国与外国签订的第一个具有近代意义的平等边界条约，此后百余年间中俄东段边境基本保持平静",
