    "ev:清帝退位": {
      "__new": true,
      "name": "清帝退位",
      "year": 1912,
      "region": "china",
      "era": "qing",
      "place": "北京（京师/顺天府）",
      "lng": 116.4,
      "lat": 39.9,
      "importance": 5,
      "blurb": "宣统帝溥仪颁布退位诏书，清朝灭亡，中国两千多年封建帝制正式终结。1912年2月12日隆裕太后代宣统帝颁退位诏书，清亡，两千余年帝制终结",
      "detail": "武昌起义后，袁世凯被起用为内阁总理大臣，一面与革命党谈判，一面逼迫清室。民国元年（1912年）2月12日，隆裕太后以宣统帝溥仪名义颁布退位诏书，宣布接受共和政体，清朝统治结束，中国两千余年的君主专制制度至此终结。诏书中“由袁世凯以全权组织临时共和政府”一语，也为后来的权力交接埋下伏笔。清帝逊位是1912年清王朝末代皇帝溥仪宣布退位、终结中国两千余年帝制的事件。武昌起义后各省纷纷独立，清朝统治土崩瓦解。为结束南北对峙、促成共和，清政府起用袁世凯，由其统率北洋军与南方革命军议和。南方革命党人以孙中山让位为条件，争取袁世凯赞成共和。1912年1月1日，中华民国临时政府在南京成立，孙中山就任临时大总统。2月12日，在袁世凯的逼迫和各方压力下，隆裕太后代表年幼的宣统帝溥仪颁布《清帝退位诏书》，宣布清帝退位，并授权袁世凯组织临时政府。至此，统治中国两千多年的君主专制制度宣告终结。清帝逊位是辛亥革命的重要成果，标志着中国进入共和的新时代，为中国社会的发展翻开了新的一页",
      "figures": [
        "溥仪",
        "袁世凯。隆裕太后",
        "袁世凯",
        "溥仪"
      ],
      "video": {
        "bili": "清帝退位。清帝退位 宣统"
      },
      "tier": 2
    },
