      "detail": "1912年1月1日，孙中山在南京就任中华民国临时大总统，宣告中华民国成立，改用公历，以1912年为民国元年，定五色旗为国旗。南京临时政府颁布了一系列革除旧俗、保护民权的法令，并于3月11日公布《中华民国临时约法》，确立主权在民与三权分立原则。这是中国历史上第一个资产阶级共和国性质的政权",
