      "detail": "1915年，袁世凯为谋求终身独裁，授意组织“筹安会”鼓吹帝制，操纵所谓“国民代表大会”投票赞成君主立宪。12月12日他宣布接受“推戴”，改国号为“中华帝国”，定1916年为洪宪元年，准备元旦登基。此举违背共和潮流，遭到全国反对，蔡锷等在云南发起护国战争，各省纷纷独立，袁被迫于1916年3月取消帝制，6月病死",
