      "detail": "前210年，始皇开始第五次出巡，左丞相李斯、少子胡亥、中车府令赵高随行。巡游至平原津时病重，始皇恶言死，群臣莫敢言后事。七月病逝于沙丘平台，年五十。宦官赵高扣留遗诏与玺印未发，秘不发丧，尸体与臭鱼同车运回咸阳，一场改变秦朝命运的密谋由此展开",
