      "detail": "在陆续翦除异姓王的过程中，刘邦与群臣杀白马盟誓：“非刘氏而王，天下共击之；非功臣而侯，天下共诛之。”此盟约以血缘与功勋为封爵的双重门槛，旨在巩固刘氏天下、约束权臣。高祖死后吕后欲封诸吕为王，右丞相王陵即援引白马之盟力争。这一盟约成为两汉维护刘姓正统的政治法理依据，也在后世多次政争中被反复援引",
