      "detail": "文帝十三年，齐太仓令淳于意获罪当刑，其少女缇萦随父至长安上书，愿没入官婢以赎父刑。文帝怜悲其意，感叹“刑罚至断肢体、刻肌肤，终身不息”，遂下诏废除黥、劓、刖等肉刑，改以笞刑、徒刑代替；后因笞数过多反多致死，景帝时又减笞数、定箠令。这是中国法制史上从肉刑向徒刑过渡的重要节点，体现德政色彩，史称“刑罚大省”",
