      "importance": 4,
      "blurb": "汉武帝晚年巫蛊之祸牵连甚广，太子刘据被逼自杀，震动朝野。汉武帝晚年巫蛊之祸致太子冤死，事后醒悟族灭江充，又下轮台诏悔过更政休民",
      "detail": "汉武帝晚年迷信方术、猜忌多疑，公元前91年，宠臣江充借查处巫蛊之事陷害太子刘据，诬称太子行巫蛊诅咒皇帝。太子刘据百口莫辩，被迫起兵诛杀江充，与丞相刘屈氂所率军队在长安激战，兵败后逃亡，最终自杀身亡，皇后卫子夫亦自杀，史称巫蛊之祸，牵连死者数万。事后汉武帝逐渐醒悟，查明太子冤情，族灭江充及其党羽，并修建思子宫、归来望思之台以寄托哀思。公元前89年，他颁布轮台诏，拒绝桑弘羊等人增戍屯田的建议，检讨自己征伐过甚、劳民伤财之失，转而推行“禁苛暴、止擅赋、力本农”的休养生息政策，为昭宣中兴创造了条件",
