      "detail": "武帝晚年连年征伐、大兴功作，海内虚耗、户口减半。前89年，桑弘羊等建议在轮台屯田戍边、继续用兵，武帝深悔征伐劳民，下诏深陈既往之悔，斥“扰劳天下，非所以优民也”，罢轮台之屯，拒绝再战；同时封丞相田千秋为富民侯，以赵过为搜粟都尉推广代田法，转向休养生息。史称“轮台诏”是晚年自我否定、扭转国策的关键文件，为昭宣中兴奠定转向基础",
