      "detail": "武帝临终前，因太子早亡，立幼子刘弗陵为太子，为防母壮子幼重演吕后之事，先赐死其母钩弋夫人。又命霍光为大司马大将军、金日磾、上官桀、桑弘羊、田千秋受遗诏共同辅政。昭帝年仅八岁即位，政事一决于霍光。霍光轻徭薄赋、与民休息、因循守成，海内渐安；他先后粉碎燕王旦与上官桀、桑弘羊的政变图谋，又于前74年废短命的昌邑王刘贺，立宣帝，成为汉代权臣辅政的标志性人物",
