      "detail": "汉宣帝刘询幼年因巫蛊之祸长于民间，深知百姓疾苦与吏治得失。即位后勤政察吏，主张“霸王道杂之”，整顿吏治、考核黜陟，屡免田租、假公田贷种食；对外前68年霍光死后逐步收回霍氏权柄，族灭霍氏，彻底亲政。宣帝时吏称其职、民安其业，设西域都护、匈奴呼韩邪来朝，西汉国力臻于极盛，史称“孝宣中兴”，为西汉治世之殿军",
