      "blurb": "西汉末年外戚王氏家族把持朝政，王莽逐步篡权，最终代汉建新",
      "detail": "元帝皇后王政君历经元、成、哀、平四朝。元帝死后成帝即位，重用母舅王凤为大司马大将军领尚书事，王氏兄弟五人同日封侯，王氏子弟分据要职，郡国守相刺史多出其门。成帝终日宴乐，政事尽委王氏；哀帝曾抑王氏抬董贤，但早死无嗣；平帝年幼，太皇太后王政君临朝，王氏复起。外戚专权半个世纪，皇权旁落，为王莽代汉铺平了道路",
