      "importance": 5,
      "blurb": "汉明帝遣使求法，佛教正式传入中原，洛阳白马寺成为中国第一座佛教寺院",
      "detail": "据传，汉明帝夜梦金人，遣使西行求法。使者在大月氏国遇天竺高僧摄摩腾、竺法兰，以白马驮佛经与佛像返回洛阳。永平十年（67年），明帝在洛阳城西建精舍安置僧人，并译出《四十二章经》，这是佛教正式传入中原的标志性事件。佛教的传入不仅带来了新的宗教信仰，也促进了中外文化交流。此后，佛经翻译逐渐展开，佛教思想开始与中国本土的儒、道思想交融。尽管初期传播范围有限，但为魏晋南北朝时期佛教的广泛传播奠定了基础，对中国哲学、艺术与社会生活产生了深远影响",
