      "blurb": "东汉窦固出击北匈奴，收复河西走廊，重新打通丝绸之路",
      "detail": "永平十六年（73年），汉明帝为解除北匈奴对边疆的威胁，命奉车都尉窦固率军出酒泉，进击北匈奴。窦固在天山一带大败匈奴呼衍王，斩首千余级，追击至蒲类海（今新疆巴里坤湖），并占领伊吾卢城（今哈密），设宜禾都尉屯田驻守。此战是东汉对匈奴的首次大规模主动出击，打破了匈奴长期控制西域的局面，为班超后续经营西域创造了有利条件。窦固的胜利不仅提振了汉军士气，也标志着东汉对外战略由守转攻，重新确立了对西北边疆的影响力，具有重大军事与地缘政治意义",
