      "detail": "梁冀是东汉顺帝、桓帝时期的外戚权臣，其妹为顺帝皇后。他凭借外戚身份长期把持朝政，专横跋扈，结党营私，甚至毒杀汉质帝，拥立汉桓帝。梁冀家族权倾朝野，贪腐成风，其宅第奢华逾制，宾客盈门，俨然跋扈将军。桓帝成年后深感其威胁，于延熹二年（159年）联合宦官单超等人发动政变，逼梁冀自杀，并诛灭其全族。梁冀之死标志着外戚专权的暂时终结，但宦官势力随即崛起。其专权过程暴露了东汉后期皇权虚弱、制度失衡的深层危机，成为戚宦之争的典型缩影",
