      "detail": "中平六年（189年），灵帝驾崩，少帝刘辩即位，外戚何进与宦官集团矛盾激化。何进召凉州军阀董卓入京助阵，事泄被宦官所杀，袁绍等又尽诛宦官。董卓趁乱率军入洛阳，废少帝，立献帝，自封相国，独揽朝政。他残暴专横，纵兵劫掠，迁都长安，焚毁洛阳，致使关中残破，民不聊生。董卓之乱彻底摧毁了东汉中央权威，激起关东诸侯联合讨伐。虽董卓后被吕布所杀，但其引发的军阀混战已不可收拾。这场动乱标志着东汉政权实质性瓦解，地方割据全面展开，为三国分立铺平道路",
