    "ev:白帝托孤": {
      "__new": true,
      "name": "白帝托孤",
      "year": 223,
      "region": "china",
      "era": "3k",
      "place": "重庆奉节（白帝城）",
      "lng": 109.5,
      "lat": 31,
      "importance": 5,
      "blurb": "刘备兵败夷陵后病逝白帝城，托孤于诸葛亮，上演千古君臣佳话。刘备病危之际在白帝城将幼子刘禅与蜀汉江山托付诸葛亮，成就君臣相得的千古典范",
      "detail": "公元223年春，刘备在夷陵惨败后病重于白帝城永安宫。临终前，他召丞相诸葛亮与李严至榻前，将国事与幼子刘禅托付二人。刘备对诸葛亮言其才十倍曹丕必能安国终定大事若嗣子可辅辅之如其不才君可自取。诸葛亮涕泣誓死效忠。刘备又命刘禅事丞相如父。此次托孤不仅是政治安排，更是君臣信任的极致体现。李严为副，掌军事，但实权集中于诸葛亮。托孤后，诸葛亮全面主持蜀汉军政，开启鞠躬尽瘁的执政生涯，稳定了蜀汉政权，也为后续南征北伐奠定政治基础。公元222年，刘备在夷陵之战中大败于陆逊，仓皇退守白帝城(永安，今重庆奉节)，忧愤成疾、一病不起。次年春，刘备自知时日无多，急召丞相诸葛亮自成都赶赴永安，同时召来尚书令李严等重臣。他先将后事托付诸葛亮，把太子刘禅与蜀汉政权一并相托，并对诸葛亮说：君才十倍曹丕，必能安国，终定大事；若嗣子可辅则辅之，如其不才，君可自取。诸葛亮泣拜于地，表示愿竭尽股肱之力，效忠贞之节。刘备又遗诏刘禅，要其待诸葛亮如父、与丞相共谋国事。同年四月刘备病逝，刘禅继位。诸葛亮此后鞠躬尽瘁、悉心辅政，成为中国古代君臣相得的典范，也奠定了蜀汉日后维系政局的根基",
      "figures": [
        "刘备",
        "诸葛亮。刘备",
        "诸葛亮",
        "刘禅",
        "李严"
      ],
      "video": {
        "bili": "白帝城托孤 刘备。白帝城托孤 诸葛亮 蜀汉"
      },
      "tier": 3
    },
