      "detail": "公元228年起，诸葛亮为实现兴复汉室之志，先后五次率军北伐曹魏。首次出祁山，天水、南安、安定三郡响应，但因马谡失街亭而功败垂成；后出陈仓、围祁山、出斜谷，虽屡有斩获，终因粮运困难、国力悬殊未能突破魏国防线。北伐期间，诸葛亮严明军纪，发明木牛流马以助运输，并多次与司马懿对峙。尽管军事上未达战略目标，但北伐凝聚了蜀汉内部共识，延缓了魏国南进。234年最后一次北伐，诸葛亮屯田五丈原，与魏军相持百余日，终因积劳成疾，病逝军中，北伐事业就此终结",
