      "detail": "公元249年，魏帝曹芳赴高平陵祭扫，大将军曹爽兄弟随驾出城。太傅司马懿趁洛阳空虚，以郭太后名义发动政变，迅速控制京城武库与城门，并上奏列举曹爽罪状，迫其交出兵权。曹爽犹豫不决，最终投降，不久被司马懿以谋反罪诛灭三族。此次政变彻底清除曹魏宗室实权派，司马氏全面掌控朝政。司马懿虽不久病逝，但其子司马师、司马昭相继掌权，废立皇帝，铲除异己，为日后篡魏建晋铺平道路。高平陵之变是曹魏政权由盛转衰的转折点，标志着门阀士族与军事强人结合的政治格局正式形成",
