      "detail": "宋文帝刘义隆为收复河南失地，于430年、450年、452年三次发动北伐，史称元嘉北伐。前两次因准备不足、将领不和而失败；第三次虽趁北魏与柔然交战之机取得局部进展，但终因后勤不继、指挥失误而溃败。北魏太武帝拓跋焘乘势南下，兵临长江，江淮地区遭受严重破坏。元嘉北伐的失败，不仅未能收复失地，反而耗尽国力，导致邑里萧条元嘉之政衰矣。此役标志着刘宋由盛转衰，南北实力对比进一步向北朝倾斜",
