      "blurb": "安史之乱中唐玄宗逃至马嵬坡，将士杀杨国忠逼死杨贵妃，盛唐终结。",
      "detail": "756年，安禄山叛军攻破潼关，逼近长安，唐玄宗仓皇携杨贵妃、杨国忠及部分禁军西逃入蜀。行至马嵬驿（今陕西兴平一带），随行的禁军将士饥疲交加、怨愤积压，认为祸乱由杨国忠而起。在陈玄礼等人的率领下，禁军哗变，杀死宰相杨国忠及其亲属，并进而要求处死杨贵妃。玄宗无奈，被迫赐杨贵妃自缢，史称马嵬驿之变。此后玄宗继续入蜀，太子李亨则北上灵武即位，是为唐肃宗。此变标志着玄宗时代的终结，也推动了唐朝平叛与政局的重组。杨贵妃之死更成为后世诗词歌咏不绝的悲剧题材",
