    "ev:世宗改革": {
      "__new": true,
      "name": "世宗改革",
      "year": 954,
      "region": "china",
      "era": "五代十国",
      "place": "河南开封（汴州）",
      "lng": 114.3,
      "lat": 34.8,
      "importance": 4,
      "blurb": "后周世宗柴荣励精图治、南征北战，为北宋统一奠定基础。954至959年周世宗柴荣整顿军政、均定赋税、南征北伐，励精图治，为北宋统一奠定基础",
      "detail": "柴荣即位，是为后周世宗。他立志“十年开拓天下，十年养百姓，十年致太平”，大力整顿禁军、裁汰老弱、均定田赋、疏浚漕运、规范法度，并限制佛教、毁铜像铸钱。这些措施使后周国力明显增强，军队战斗力大幅提升，为后来北宋的统一事业提供了制度与军事基础。五代后周显德元年（954年），周太祖郭威去世，养子柴荣即位，是为后周世宗。即位之初，北汉联合契丹南犯，柴荣力排众议，亲征高平，大败敌军，稳固了政权。此后他锐意改革：整顿禁军，汰弱留强，组建精锐的殿前军；均定赋税，减轻民负，招抚流民、恢复农桑；限制佛教，裁汰寺院僧尼以充实户籍财赋；并整修水利、治理黄河、疏通漕运。军事上他南征南唐，取得江北十四州；又北伐辽朝，收复瀛、莫等州。柴荣励精图治，志在统一，惜于959年英年早逝，年仅三十九岁。他的改革扭转了五代积弊，大大增强了后周国力，为赵匡胤建立北宋、完成统一奠定了坚实基础",
      "figures": [
        "柴荣。柴荣",
        "王朴",
        "赵匡胤"
      ],
      "video": {
        "bili": "周世宗改革。周世宗 柴荣 后周世宗改革"
      },
      "tier": 3
    },
