      "detail": "明仁宗洪熙与明宣宗宣德（1426—1435年）年间，朝廷实行休养生息政策：减免赋税、平反冤狱、任用“三杨”（杨士奇、杨荣、杨溥）辅政，停止大规模用兵与远洋航行，并设立内阁票拟制度以提高行政效率。这一时期政治清明、经济恢复、社会安定，被视为明代国力最强盛的阶段之一",
