    "ev:智擒鳌拜": {
      "__new": true,
      "name": "智擒鳌拜",
      "year": 1669,
      "region": "china",
      "era": "qing",
      "place": "北京（京师/顺天府）",
      "lng": 116.4,
      "lat": 39.9,
      "importance": 4,
      "blurb": "少年康熙智擒权臣鳌拜，亲政后励精图治，开创康乾盛世。1669年少年康熙以布库少年智擒权臣鳌拜，夺回朝政大权，由此开始亲政",
      "detail": "康熙八年（1669年），十六岁的康熙帝以练习摔跤为名，挑选一批少年侍卫日日操练，趁鳌拜入宫议事时将其擒拿，随后公布其三十条罪状，予以囚禁（未处死），并清除其党羽。此举结束了辅政大臣专权的局面，康熙真正掌握实权，开始亲自主持朝政，开启其后六十余年的统治。顺治帝去世后，年仅八岁的玄烨即位，是为康熙帝，由索尼、苏克萨哈、遏必隆、鳌拜四大臣辅政。鳌拜战功显赫却专横跋扈，结党营私，屡次矫诏排挤异己，甚至杀害苏克萨哈，朝政大权旁落其手，皇权受到严重威胁。康熙帝虽年少，却深藏机锋，表面隐忍，暗中选择一批少年侍卫在宫中练习布库（摔跤）以掩人耳目。康熙八年（1669年），他召鳌拜入宫，命少年侍卫一举将其擒获，随即宣布其罪状，革职拘禁，并肃清其党羽。康熙帝由此夺回朝政大权，正式亲政，为其后平定三藩、统一台湾、抗击沙俄等一系列重大举措扫清了障碍，展现出少年天子的果决与胆识",
      "figures": [
        "康熙帝",
        "鳌拜。康熙",
        "鳌拜"
      ],
      "video": {
        "bili": "康熙 擒鳌拜"
      },
      "tier": 3
    },
