    "ev:设军机处": {
      "__new": true,
      "name": "设军机处",
      "year": 1729,
      "region": "china",
      "era": "qing",
      "place": "北京（京师/顺天府）",
      "lng": 116.4,
      "lat": 39.9,
      "importance": 5,
      "blurb": "约1729年雍正帝设军机处，皇帝直接掌控军政大权，军机大臣跪受笔录、承旨办事，君主专制达到顶峰",
      "detail": "因西北用兵需要保密与高效处理军务，清廷设立军机房，后改称军机处，由皇帝选派亲信大臣充任军机大臣，每日觐见承旨、拟写谕旨。军机处取代内阁成为实际中枢，议政王大臣会议名存实亡，标志着中国古代君主专制达到顶峰。军机处是清代雍正年间设立的辅佐皇帝处理军国大事的中枢机构。雍正七年（约1729年），因西北用兵、军报频繁，为便于机密快速地处理军务，雍正帝设立军机房，后改称办理军机处。军机大臣由皇帝从亲王、大学士、尚书、侍郎等亲信中亲自挑选，无固定人数，直接听命于皇帝，每日入值，跪受笔录，恭承谕旨，再迅速传达执行，办事机密而高效。军机处不设衙署属官，也无独立决策权，一切听凭皇帝裁断。军机大臣虽是皇帝最亲近的谋臣，却只是承旨办事的秘书班子，无法像前代宰相那样制约皇权。它的设立取代了议政王大臣会议的权力，使皇权高度集中，标志着清代君主专制制度发展到了顶峰，这一制度一直沿用到清末",
      "figures": [
        "雍正帝。雍正帝",
        "张廷玉",
        "鄂尔泰"
      ],
      "video": {
        "bili": "军机处 雍正"
      },
      "tier": 3
    },
