      "detail": "1949年4月20日，国民党政府拒绝在《国内和平协定》上签字。21日，毛泽东、朱德发布向全国进军的命令，第二、第三野战军百万雄师在西起湖口、东至江阴的千里战线上强渡长江，迅速突破国民党军江防。4月23日解放南京，宣告国民党22年反动统治的覆灭。随后解放军分路向南挺进，解放杭州、武汉、上海等地",
